#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    /* No argument supplied */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);

    /* Bad input: not a number or extra characters */
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* Negative numbers are not accepted */
    if (n < 0) {
        puts("BAD_INPUT");
        return 0;
    }

    /* The original program only supports n up to 30 (array size 30) */
    if (n > 30) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* The program expects a positive index (1‑based).  For n == 0 we treat it as bad input. */
    if (n == 0) {
        puts("BAD_INPUT");
        return 0;
    }

    /* Compute Catalan numbers up to n using the classic recurrence:
       C[0] = 1; C[i] = sum_{j=0}^{i-1} C[j] * C[i-1-j]
       The original binary stored the values in a 30‑element array of 64‑bit integers.
    */
    unsigned long long cat[30];
    cat[0] = 1ULL;
    for (int i = 1; i < n; ++i) {
        unsigned long long sum = 0ULL;
        for (int j = 0; j < i; ++j) {
            sum += cat[j] * cat[i - 1 - j];
        }
        cat[i] = sum;
    }

    /* The original program printed the (n‑1)‑th Catalan number (1‑based input).
       For example, input 1 prints C0 = 1, input 2 prints C1 = 1, etc.
    */
    printf("%llu\n", cat[n - 1]);
    return 0;
}
